# DISCLAMER: This file is generated by AI for testing purposes.
import math
import unittest
from pathlib import Path

import numpy as np

from iSpy import units
from iSpy.vision import triangulation
from iSpy.web.modules.viewer3d import Viewer3DModule

ROOT = Path(__file__).resolve().parents[1]


class _FakeCamera:
    def __init__(self, config):
        self.config = config


class ViewerConfigTests(unittest.TestCase):
    def test_viewer_config_matches_unit_pack(self):
        mod = Viewer3DModule({"config": {"unit": "imperial"}})
        expected = units.viewer_settings("imperial")
        self.assertEqual(mod._viewer_config(), expected)
        self.assertEqual(mod._viewer_config()["robot_to_viewer"], ["x", "z", "-y"])

    def test_page_embeds_viewer_config(self):
        mod = Viewer3DModule({"config": {"unit": "frc"}, "cameras": []})
        # Flask is not needed to render through Flask's test helpers; the
        # template simply must reference the injected config.
        template = (ROOT / "iSpy" / "web" / "templates" / "viewer3d.html").read_text(
            encoding="utf-8"
        )
        self.assertIn("viewer_config | tojson", template)
        self.assertIn("const AXIS_MAP = VIEWER_CONFIG.robot_to_viewer", template)
        self.assertIn("VIEWER_CONFIG.grid.extent", template)
        self.assertIn("VIEWER_CONFIG.scale", template)
        self.assertIn("VIEWER_CONFIG.camera", template)
        self.assertIn("VIEWER_CONFIG.fog_density", template)
        self.assertIn("VIEWER_CONFIG.axes_size", template)
        self.assertIn("robotToViewer(px, py, pz, AXIS_MAP)", template)
        self.assertEqual(len(mod.context["cameras"]), 0)

    def test_unknown_unit_falls_back_to_frc_viewer(self):
        mod = Viewer3DModule({"config": {"unit": "bogus"}})
        self.assertEqual(mod._viewer_config(), units.viewer_settings("frc"))


class CameraOverlayOrientationTests(unittest.TestCase):
    def _overlay(self, unit="frc", yaw=0.0, pitch=0.0, height=0.0, x=0.0, y=0.0):
        cam = _FakeCamera(
            {
                "name": "front",
                "x": x,
                "y": y,
                "height": height,
                "yaw": yaw,
                "pitch": pitch,
                "calibration": {"fov": 70},
            }
        )
        mod = Viewer3DModule({"config": {"unit": unit}, "cameras": [cam]})
        mod._refresh_camera_overlays()
        return mod._overlays["camera:front"]

    def test_level_camera_points_forward_not_down(self):
        overlay = self._overlay()
        # camera_rotation_to_world(identity, 0, 0) is Rx(-90): local +Z (the
        # frustum's forward axis) points along robot +Y.
        self.assertAlmostEqual(overlay["roll"], -math.pi / 2)
        self.assertAlmostEqual(overlay["pitch"], 0.0)
        self.assertAlmostEqual(overlay["yaw"], 0.0)
        rotation = triangulation.euler_to_matrix(
            overlay["roll"], overlay["pitch"], overlay["yaw"]
        )
        expected = triangulation.camera_rotation_to_world(np.eye(3), 0.0, 0.0)
        np.testing.assert_allclose(rotation, expected, atol=1e-9)

    def test_overlay_rotation_matches_physical_mount(self):
        for yaw, pitch in ((0, 0), (30, 0), (0, 20), (-45, 15), (90, 45)):
            with self.subTest(yaw=yaw, pitch=pitch):
                overlay = self._overlay(yaw=yaw, pitch=pitch)
                rotation = triangulation.euler_to_matrix(
                    overlay["roll"], overlay["pitch"], overlay["yaw"]
                )
                expected = triangulation.camera_rotation_to_world(
                    np.eye(3), yaw, pitch
                )
                np.testing.assert_allclose(rotation, expected, atol=1e-9)

    def test_overlay_position_uses_output_units(self):
        overlay = self._overlay(unit="frc", x=10, y=20, height=30)
        self.assertAlmostEqual(overlay["x"], 10 * 0.0254)
        self.assertAlmostEqual(overlay["y"], 20 * 0.0254)
        self.assertAlmostEqual(overlay["z"], 30 * 0.0254)

        imperial = self._overlay(unit="imperial", x=10, y=20, height=30)
        self.assertAlmostEqual(imperial["x"], 10)
        self.assertAlmostEqual(imperial["y"], 20)
        self.assertAlmostEqual(imperial["z"], 30)

    def test_optional_mount_trim_is_applied(self):
        pack = units._normalize_pack(
            {
                "key": "_trim",
                "input_to_inches": 1.0,
                "inches_to_output": 0.0254,
                "viewer": {"camera_pitch_offset_deg": 5.0},
            },
            "_trim",
        )
        units._PACKS["_trim"] = pack
        try:
            viewer = units.viewer_settings("_trim")
            mod = Viewer3DModule({"config": {"unit": "_trim"}})
            roll, pitch, yaw = mod._camera_orientation(0, 0, viewer)
            rotation = triangulation.euler_to_matrix(roll, pitch, yaw)
            expected = triangulation.camera_rotation_to_world(
                np.eye(3), 0.0, 0.0
            ) @ triangulation.euler_to_matrix(0.0, math.radians(5.0), 0.0)
            np.testing.assert_allclose(rotation, expected, atol=1e-9)
        finally:
            units._PACKS.pop("_trim", None)

    def test_missing_fov_uses_pack_camera_fov(self):
        cam = _FakeCamera({"name": "front", "calibration": {}})
        mod = Viewer3DModule({"config": {"unit": "frc"}, "cameras": [cam]})
        mod._refresh_camera_overlays()
        self.assertEqual(mod._overlays["camera:front"]["data"]["fov"], 60.0)

    def test_stale_camera_overlays_are_removed(self):
        mod = Viewer3DModule({"config": {"unit": "frc"}, "cameras": []})
        mod.add_overlay("camera:gone", {"type": "camera"})
        mod._refresh_camera_overlays()
        self.assertNotIn("camera:gone", mod._overlays)


class PluginStatusUnitKeyTests(unittest.TestCase):
    def test_unit_key_is_path_safe(self):
        from iSpy.web.Backend.PluginStatus import PluginStatusModule

        key = PluginStatusModule._unit_key("../../My Custom Pack!!")
        self.assertEqual(key, "my-custom-pack")
        self.assertNotIn("/", key)
        self.assertNotIn("\\", key)
        self.assertNotIn(".", key)


if __name__ == "__main__":
    unittest.main()
